list_pages.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::listPages($client, ['search' => 'about', 'visibility' => 'open', 'sort' => 'name', 'order' => 'asc']);

foreach ($response->map['pages'] as $page) {
    echo $page['id'], ' ', $page['name'], ' ', $page['url'], $page['landing'] ? ' (landing)' : '', PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;

count_pages.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::countPages($client, ['active' => true, 'has_layout' => true]);

echo $response->map['total'], PHP_EOL;

create_page.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::createPage($client, ['page' => [
    'name' => 'About us', 'title' => 'About us', 'visibility' => 'open', 'layout' => ['id' => 28],
]]);

$page = $response->map['page'];
echo $page['id'], ' ', $page['url'], ' ', $page['full_url'], PHP_EOL;

get_page.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::getPage($client, 812);

$page = $response->map['page'];
echo $page['name'], ' ', $page['url'], ' ', $page['visibility'], $page['active'] ? ' active' : ' inactive', PHP_EOL;

update_page.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::updatePage($client, 812, ['page' => [
    'name' => 'About us', 'title' => 'About us', 'subtitle' => 'Who we are', 'url' => 'about-us',
    'layout' => ['id' => 28], 'visibility' => 'open', 'body_class' => 'about-page', 'active' => true,
    'disable_tracking' => false, 'password_protection' => ['enabled' => false],
]]);

$page = $response->map['page'];
echo $page['title'], ' - ', $page['subtitle'], ' ', $page['body_class'], PHP_EOL;

patch_page.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::patchPage($client, 812, ['page' => ['title' => 'About our company']]);

echo $response->map['page']['title'], PHP_EOL;

set_landing_page.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::setLandingPage($client, 812);

$page = $response->map['page'];
echo $page['name'], $page['landing'] ? ' is the landing page' : ' is not the landing page', PHP_EOL;

get_page_delete_blockers.code:
use WebCommander\Sdk\Resources\Pages\Pages;

$response = Pages::getPageDeleteBlockers($client, 812);

echo $response->map['can_delete'] ? 'can delete' : 'cannot delete', PHP_EOL;
foreach ($response->map['blockers'] as $blocker) {
    echo $blocker['code'], ': ', $blocker['message'], PHP_EOL;
}
